   $('[data-bp-convert-apply]',host).onclick=()=>api.work(async()=>{if(!preview||!$('[data-bp-convert-ack]',host).checked||inputs.get(k)?.text!==exact)throw Error('현재 본문과 보존 범위를 다시 확인하세요. 입력은 유지됩니다.');guard(preview.observedIds);const result=await api.view.call('blueprint',{action:'convertBody',id:preview.id,target:preview.target,basis:preview.basis});if(inputs.get(k)?.text===exact){inputs.delete(k);api.close(w);}const list=await api.view.call('blueprint',{action:'list'}),data=await read(result.id),main=api.windows.get('blueprint');api.reveal('blueprint');api.focus(show(data,main?.meta||{},list));refreshCode(data);api.persist();},'기존 본문을 단일 코드 노드 초안으로 전환했습니다. 원본 파일은 보존하며 Review/Confirm은 별도입니다.');api.controls();
