  if(lines.length===breaks.length+1)return lines.map((line,i)=>line+(breaks[i]||'')).join('');
  const prior=original.replace(/\r\n|\r/g,'\n').split('\n');let prefix=0,suffix=0;
  while(prefix<Math.min(prior.length,lines.length)&&prior[prefix]===lines[prefix])prefix++;
