  const fallback=breaks.every(value=>value===breaks[0])?(breaks[0]||'\n'):'\n';
  return lines.map((line,i)=>line+(i===lines.length-1?'':i<prefix?breaks[i]:i>=lines.length-suffix?breaks[prior.length-(lines.length-i)]:fallback)).join('');
